UPN_length.inputs:
@if(
    greater(
        length(
            first(
                split(
                    outputs('Generate_Knowledge_UPN'),
                    '@'
                )
            )
        ),
        40
    ),
    concat(
        substring(
            first(
                split(
                    outputs('Generate_Knowledge_UPN'),
                    '@'
                )
            ),
            0,
            40
        ),
        '@elcarwash.com'
    ),
    outputs('Generate_Knowledge_UPN')
)
